  function checks(p){const w=normalize(p);const findings=[];if(!p.question.trim())findings.push('Record a research question.');if(!w.design.length)findings.push('Add at least one objective and methods plan.');for(const [i,d] of w.design.entries())for(const [key,label] of Object.entries({objective:'objective',measure:'measure or construct',collection:'collection method',analysis:'analysis plan',rationale:'alignment rationale',population:'population or setting',sample:'sample or selection',ethics:'ethics and privacy plan',feasibility:'feasibility plan',output:'expected output or result'}))if(!d[key].trim())findings.push('Objective '+(i+1)+': add '+label+'.');const linked=new Set();for(const [i,c] of w.claims.entries()){if(!c.links.length)findings.push('Claim '+(i+1)+' has no linked evidence.');for(const l of c.links)linked.add(l.evidenceId);if(c.links.some(l=>l.relation==='challenges'))findings.push('Claim '+(i+1)+' has challenging evidence to address.');if(c.links.length===1)findings.push('Claim '+(i+1)+' relies on one evidence note; compare another source if possible.')}for(const [i,n] of p.evidence.entries())if(!linked.has(n.id))findings.push('Evidence E'+(i+1)+' is not connected to a claim yet.');for(const [i,c] of w.comparisons.entries())if(!c.explanation.trim())findings.push('Comparison '+(i+1)+' needs an explanation before it can inform synthesis.');if(p.proposal.trim()&&!w.claims.length)findings.push('Proposal text exists, but no claims are recorded in the evidence trail.');if(w.impact)findings.push('Your question changed: review the objectives, evidence, and draft.');return findings}
