  const form=(kind,title,body)=>`<details class="research-add"><summary>${title}<span>+</span></summary><form class="research-form" data-wb-form="${kind}">${body}<button class="button primary">Save ${title.toLowerCase().replace(/^add /,'').replace('reviewaction','review action')}</button></form></details>`;
