  function libraryTools(){return `<section class="wb-tools"><p class="eyebrow">BRING YOUR SOURCES WITH YOU</p><h3>Import once. Keep the context.</h3><p>CSV, RIS, or standard BibTeX records. Review missing titles and duplicates before saving. PDF files are added in the Reader.</p><label class="button secondary">Choose reference file<input id="wb-import" type="file" accept=".csv,.ris,.bib,.bibtex" aria-label="Import references"></label><p class="wb-hint">CSV columns: title, authors, year, doi, url, venue, abstract, collection. Complex BibTeX macros are not expanded; review the preview.</p><div id="wb-import-preview" aria-live="polite"></div><div class="actions">${button('Export bibliography','bibliography')}${button('Export library CSV','library-csv')}</div></section>`}
