  function synthesis(){const p=get(),w=state(),audit=C.sourceAudit(p);return heading('See the patterns across your sources.','Code evidence notes with researcher-defined themes, then compare the matrix before drawing a conclusion. REI does not infer themes or score agreement.')+`<div class="wb-synthesis-overview"><div><strong>${w.codes.length}</strong><span>Themes</span></div><div><strong>${w.coding.length}</strong><span>Coded notes</span></div><div><strong>${p.evidence.length}</strong><span>Evidence notes</span></div><div><strong>${audit.length}</strong><span>Source audit items</span></div></div>${form('code','Add theme',input('Theme name','label','',true)+area('What makes a note belong to this theme?','definition')+`<label>Theme color<select name="color">${themeColors.map(c=>`<option value="${c}">${c}</option>`).join('')}</select></label>`)}${w.codes.length?`<section class="wb-section"><h3>Your themes</h3><div class="wb-theme-list">${w.codes.map(c=>`<article class="wb-theme" style="--theme:${esc(c.color)}"><span class="wb-theme-swatch" aria-hidden="true"></span><div><h4>${esc(c.label)}</h4><p>${esc(c.definition||'No definition recorded.')}</p></div><span>${w.coding.filter(x=>x.codeId===c.id).length} notes</span>${button('Remove theme','code-remove',c.id)}</article>`).join('')}</div></section>`:empty('Add a theme to start coding.','Use a short label such as access, mechanism, outcome, limitation, or disagreement.')}${p.evidence.length?`<section class="wb-section"><h3>Synthesis matrix</h3><p>Each row is a researcher-authored evidence note. Add a theme and a short coding memo; a note may receive more than one theme.</p><div class="wb-synthesis-table-wrap"><table class="wb-synthesis-table"><caption>Evidence by theme</caption><thead><tr><th scope="col">Evidence</th><th scope="col">Source</th><th scope="col">Finding / relevance</th><th scope="col">Method · context</th><th scope="col">Limitations</th>${w.codes.map(c=>`<th scope="col"><span class="wb-theme-dot" style="background:${esc(c.color)}"></span>${esc(c.label)}</th>`).join('')}<th scope="col">Coding memo</th></tr></thead><tbody>${p.evidence.map((n,i)=>{const coded=w.coding.filter(x=>x.evidenceId===n.id);return `<tr><th scope="row">E${i+1}</th><td>${esc(p.papers.find(s=>s.id===n.paperId)?.title||'Source removed')}</td><td>${esc([n.findings,n.relevance].filter(Boolean).join('\n\n')||'Not recorded')}</td><td>${esc([n.method,n.context].filter(Boolean).join(' · ')||'Not recorded')}</td><td>${esc(n.limitations||'Not recorded')}</td>${w.codes.map(c=>`<td>${coded.some(x=>x.codeId===c.id)?'<span class="wb-coded" title="Coded in this theme">●</span>':'<span class="wb-uncoded">·</span>'}</td>`).join('')}<td>${coded.map(x=>`<span class="wb-coding-chip">${esc(w.codes.find(c=>c.id===x.codeId)?.label||'Theme')}: ${esc(x.note||'No memo')}${button('Remove coding','coding-remove',x.id)}</span>`).join('')||'<span class="wb-hint">Not coded yet</span>'}</td></tr>`}).join('')}</tbody></table></div><div class="actions">${button('Export synthesis matrix CSV','synthesis-csv')}</div>${w.codes.length?form('coding','Code an evidence note',`<label>Evidence note<select name="evidenceId">${noteOptions()}</select></label><label>Theme<select name="codeId">${codeOptions()}</select></label>${area('Coding memo','note')} `):'<p>Add a theme before coding evidence.</p>'}</section>`:empty('Add evidence before building a synthesis matrix.','Your evidence notes become the rows of the matrix.')}${audit.length?`<section class="wb-section wb-audit-preview"><h3>Source audit preview</h3><ul>${audit.slice(0,6).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><a class="text-link" href="#research/${esc(p.id)}/review">Open the full review queue ↗</a></section>`:''}`}
 function reader(){return heading('Read closely. Keep the evidence.','Attach a PDF you have permission to use. Select words in the extracted page text and capture a source-linked passage.')+(get().papers.length?`<div class="wb-reader-controls"><label>Source paper<select id="wb-reader-source">${sourceOptions()}</select></label><label class="button secondary">Attach PDF<input id="wb-pdf" type="file" accept=".pdf,application/pdf" aria-label="Attach local PDF"></label>${button('Open saved PDF','pdf-open')}</div><p class="wb-hint">Up to 20 MB per PDF and 60 MB per project. Files stay in this browser. Include PDFs when exporting a complete backup.</p><div class="wb-reader"><section><div class="actions">${button('Previous page','page-prev')}<label>Page<input id="wb-page" type="number" value="1" min="1" aria-label="PDF page"></label>${button('Go','page-go')}${button('Next page','page-next')}</div><p id="wb-pdf-status" role="status">Choose a paper and open or attach its PDF.</p><canvas width="0" id="wb-pdf-canvas" aria-label="Rendered PDF page"></canvas><details open><summary>Selectable page text</summary><div id="wb-pdf-text" tabindex="0" aria-label="PDF page text" class="wb-page-text"></div></details><p class="wb-hint">Scanned pages may have no selectable text; OCR is not included. Page numbers refer to PDF pages.</p></section><section><form data-wb-form="passage" class="research-form"><h3>Capture a passage</h3><label>What are you looking for?<select name="readingRole">${Object.entries(window.REILibraryCore.readingRoles).map(([key,role])=>`<option value="${key}">${esc(role.label)}</option>`).join('')}</select></label><div id="wb-reading-guide" class="wb-reading-guide" role="status"></div>${button('Use selected text','capture')}${area('Exact passage','quote','',true)}${area('Your interpretation / finding','findings','',true)}${area('Relevance to your question','relevance')}<button class="button primary">Save passage as evidence</button></form><p class="wb-hint">Check the passage against the original page before saving. Your interpretation remains separate from the quotation.</p><div id="wb-reader-notes"></div></section></div>`:empty('Add a source first.','Open Library and add or import a paper before attaching its PDF.'))}
 function claims(){const p=get(),w=state();return heading('Build an argument you can trace.','Claims are your interpretations. Link recorded evidence and describe whether it supports, challenges, or complicates the claim.')+form('claim','Add claim',area('Claim statement','text','',true))+w.claims.map((c,i)=>`<article class="wb-record" id="claim-${esc(c.id)}"><span class="eyebrow">CLAIM ${i+1} · ${esc(c.status)}</span><h3>${esc(c.text)}</h3><ul class="wb-links">${c.links.map(l=>{const n=p.evidence.find(n=>n.id===l.evidenceId);return `<li><strong>${esc(l.relation)}</strong> · E${p.evidence.indexOf(n)+1} · ${esc(n?.findings)}<p>${esc(p.papers.find(s=>s.id===n?.paperId)?.title)} ${esc(n?.locator)}</p>${button('Unlink','unlink',c.id+'|'+l.evidenceId)}</li>`}).join('')||'<li>No evidence linked yet.</li>'}</ul>${p.evidence.length?`<form data-wb-form="link" class="wb-inline"><input type="hidden" name="claimId" value="${esc(c.id)}"><label>Evidence note<select name="evidenceId">${noteOptions()}</select></label><label>Relationship<select name="relation">${['supports','challenges','mixed','uncertain'].map(x=>`<option>${x}</option>`).join('')}</select></label><button class="button secondary">Link evidence</button></form>`:'<p>Add evidence notes before linking this claim.</p>'}<div class="actions">${button('Insert with sources into proposal','claim-insert',c.id)}${button(c.status==='Reviewed'?'Mark tentative':'Mark reviewed','claim-status',c.id)}${button('Edit claim','claim-edit',c.id)}${button('Remove claim','claim-remove',c.id)}</div></article>`).join('')+(!w.claims.length?empty('Your argument starts here.','Write one claim, then connect the evidence behind it.'):'')}
 function alignmentPanel(p,w){const rows=C.alignment(p);return `<section class="wb-section wb-alignment"><h3>Method alignment worksheet</h3><p>Check that every objective has a population, sample, measure, collection plan, analysis plan, ethics plan, feasibility plan, expected output, and rationale. These are prompts for discussion, not a scientific score.</p>${rows.length?`<div class="wb-alignment-list">${rows.map(r=>`<article class="wb-alignment-row ${r.ready?'ready':''}"><span class="wb-alignment-status" aria-label="${r.ready?'Complete':'Needs attention'}">${r.ready?'✓':'○'}</span><div><strong>Objective ${r.index}: ${esc(r.objective||'Untitled objective')}</strong><p>${r.ready?'All alignment fields recorded.':r.gaps.map(k=>k.replace(/([A-Z])/g,' $1')).join(' · ')+' still needed.'}</p></div></article>`).join('')}</div>`:empty('Add an objective to check alignment.','A clear objective gives the rest of the method plan something to answer.')}</section>`} function design(){const p=get(),w=state(),issues=C.checks(p),readiness=C.readiness(p);return heading('Make the research design fit.','Transparent completeness checks and your own alignment rationale. REI does not certify scientific validity.')+alignmentPanel(p,w)+`<section class="wb-checks"><h3>Research readiness map</h3><div class="wb-readiness">${readiness.map(r=>`<div class="wb-readiness-item ${r.ready?'ready':''}"><span aria-hidden="true">${r.ready?'✓':'○'}</span><strong>${esc(r.label)}</strong><small>${r.ready?'Recorded':'Needs attention'}</small></div>`).join('')}</div><h3>${issues.length?issues.length+' '+(issues.length===1?'point':'points')+' to review':'Recorded fields are complete'}</h3><ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Ask a supervisor to review the substance of your design.</li>'}</ul>${w.impact?button('I reviewed the question change','impact-reviewed'):''}</section>`+form('design','Add objective',area('Objective','objective','',true)+area('Measure or construct','measure')+area('Collection method / sampling','collection')+area('Analysis plan','analysis')+area('What or who is being studied','population')+area('Sample or selection','sample')+area('Ethics, consent, privacy, and risk','ethics')+area('Time, access, and resources','feasibility')+area('Expected output or result','output')+area('Why this answers the research question','rationale'))+w.design.map((d,i)=>`<article class="wb-record"><span class="eyebrow">OBJECTIVE ${i+1}</span><h3>${esc(d.objective)}</h3><dl>${['measure','population','sample','collection','analysis','ethics','feasibility','output','rationale'].map(k=>`<dt>${esc(k)}</dt><dd>${esc(d[k]||'Not recorded')}</dd>`).join('')}</dl><div class="actions">${button('Edit objective','design-edit',d.id)}${button('Remove objective','design-remove',d.id)}</div></article>`).join('')+`<section class="wb-section"><h3>Coverage explorer</h3><p>Compare only the evidence in this project. Missing cells show missing notes, not proof that the literature has a gap.</p><div class="evidence-table-wrap"><table class="evidence-table"><caption>Coverage in your reviewed collection</caption><thead><tr><th>Source</th><th>Population / context</th><th>Method</th><th>Limitations</th></tr></thead><tbody>${p.evidence.map(n=>`<tr><th>${esc(p.papers.find(s=>s.id===n.paperId)?.title)}</th><td>${esc(n.context||'Not recorded')}</td><td>${esc(n.method||'Not recorded')}</td><td>${esc(n.limitations||'Not recorded')}</td></tr>`).join('')}</tbody></table></div></section><section class="wb-section"><h3>Contradiction workbench</h3><p>Compare findings, contexts, and methods before deciding whether two results conflict.</p>${p.evidence.length>1?form('comparison','Add comparison',`<label>First evidence note<select name="left">${noteOptions()}</select></label><label>Second evidence note<select name="right">${noteOptions()}</select></label>${area('How do they differ, and what might explain it?','explanation','',true)}`):'<p>Add at least two evidence notes to compare findings.</p>'}${w.comparisons.map(c=>`<article class="wb-record"><div class="wb-columns">${[c.left,c.right].map(id=>{const n=p.evidence.find(x=>x.id===id);return `<div><h4>${esc(p.papers.find(s=>s.id===n?.paperId)?.title)}</h4><p>${esc(n?.findings)}</p><p>Method: ${esc(n?.method||'Not recorded')}</p><p>Context: ${esc(n?.context||'Not recorded')}</p></div>`}).join('')}</div><p>${esc(c.explanation)}</p>${button('Remove comparison','comparison-remove',c.id)}</article>`).join('')}</section>`}
 function graph(){const p=get(),w=state();return heading('Follow the research connections.','A project model built from your recorded links. Expand a claim to follow its evidence back to the source.')+`<div class="wb-model"><div class="wb-question"><span class="eyebrow">RESEARCH QUESTION</span><h3>${esc(p.question||'Record your research question in project details.')}</h3></div><div class="wb-model-grid">${w.claims.map((c,i)=>`<details class="wb-model-node"><summary><span>CLAIM ${i+1}</span>${esc(c.text)}</summary>${c.links.map(l=>{const n=p.evidence.find(n=>n.id===l.evidenceId),s=p.papers.find(s=>s.id===n?.paperId);return `<div class="wb-model-evidence"><strong>${esc(l.relation)}</strong><p>${esc(n?.findings)}</p><blockquote>${esc(n?.quote||'No exact passage recorded.')}</blockquote><p>Source: ${esc(s?.title)} · ${esc(n?.locator||'Location not recorded')}</p></div>`}).join('')||'<p>No evidence connected.</p>'}</details>`).join('')||'<p>Add claims and evidence links to grow this view.</p>'}</div><div class="wb-model-methods"><h3>Methods plan</h3>${w.design.map(d=>`<details><summary>${esc(d.objective)}</summary><p>${esc(d.rationale)}</p><p>${esc(d.collection)} → ${esc(d.analysis)}</p></details>`).join('')||'<p>No objectives recorded.</p>'}</div></div><p class="wb-hint">This is an accessible project outline, not an inferred citation network. The literature map remains available below.</p>`}
 const prompts=p=>['What is the precise question your project answers?','Which evidence most strongly supports your main claim?','What evidence challenges your interpretation?','Why can your collection and analysis methods answer this question?','What limitations would change your conclusion?','How will you explain the scope of your literature search?'];
 function reviewHTML(){const lines=report().split('\n');return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(get().title)+' · REI review</title><style>body{font:17px/1.75 system-ui,sans-serif;color:#172337;background:#f2f5f8;margin:0}main{max-width:850px;margin:auto;padding:48px 28px}h1{font-size:2.5rem;line-height:1.2}h2{border-top:1px solid #b8c7d7;padding-top:26px;margin-top:42px}h3{color:#204c67}p{overflow-wrap:anywhere;white-space:pre-wrap;margin:8px 0}.brand{letter-spacing:.16em;color:#345e72}footer{border-top:1px solid #b8c7d7;margin-top:40px;padding-top:18px}@media print{body{background:white}main{padding:0}h2,h3{break-after:avoid}}</style><main><p class="brand">REI / RESEARCH REVIEW</p>'+lines.map(line=>{const h=line.match(/^(#{1,3}) (.*)$/);return h?`<h${h[1].length}>${esc(h[2])}</h${h[1].length}>`:line?'<p>'+esc(line)+'</p>':''}).join('')+'<footer>This file contains a review copy. It cannot restore your workspace; retain the separate JSON backup.</footer></main></html>'}
 function reviewActionQueue(p,w){const checks=C.checks(p),audit=C.sourceAudit(p),resolved=new Set(w.reviewResolved||[]),openChecks=checks.filter(x=>!resolved.has(x)),manual=(w.reviewActions||[]).filter(x=>x.status!=='Done');return `<section class="wb-action-queue"><div class="wb-queue-head"><div><span class="eyebrow">NEXT RESEARCH ACTIONS</span><h3>Turn gaps into the next move.</h3><p>These prompts are generated from your recorded work. Mark an item done only after you have reviewed the underlying evidence.</p></div><strong>${openChecks.length+manual.length} open</strong></div><ul class="wb-action-list">${openChecks.map(x=>`<li><span class="wb-action-kind">CHECK</span><span>${esc(x)}</span>${button('Mark done','review-done',encodeURIComponent(x))}</li>`).join('')}${manual.map(x=>`<li><span class="wb-action-kind">${esc(x.area||'ACTION')}</span><span>${esc(x.text)}${x.date?`<small>${esc(new Date(x.date).toLocaleDateString())}</small>`:''}</span>${button('Mark done','review-action-done',x.id)}${button('Remove','review-action-remove',x.id)}</li>`).join('')||(!openChecks.length?'<li class="wb-action-empty">No open actions. Ask a supervisor to review the substance of the work.</li>':'')}</ul>${form('reviewAction','Add review action',input('Action to complete','text','',true)+input('Area or label','area','Methods, ethics, evidence'))}</section><section class="wb-section wb-source-audit"><div class="wb-queue-head"><div><span class="eyebrow">SOURCE AUDIT</span><h3>Check the trail before sharing.</h3><p>Metadata and location prompts help a reviewer verify what each source contributes. They do not judge study quality.</p></div><strong>${audit.length?audit.length+' items':'Clear'}</strong></div>${audit.length?`<ul class="wb-audit-list">${audit.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="wb-audit-clear">No source audit prompts are open.</p>'}<div class="actions">${button('Export source audit CSV','source-audit')}</div></section>`}
 function supervisorPacket(){const p=get(),w=state(),audit=C.sourceAudit(p),alignment=C.alignment(p),checks=C.checks(p),open=checks.filter(x=>!(w.reviewResolved||[]).includes(x));return `# ${p.title} — supervisor review packet

## Student research question
${p.question||'Not recorded'}

## Review status
Open generated actions: ${open.length}
Open source audit items: ${audit.length}
Themes: ${w.codes.length} · Coded evidence notes: ${w.coding.length}

## Actions to discuss
${open.concat((w.reviewActions||[]).filter(x=>x.status!=='Done').map(x=>x.text)).map(x=>'- '+x).join('\n')||'- No open actions recorded.'}

## Source audit
${audit.map(x=>'- '+x).join('\n')||'No source audit prompts are open.'}

## Method alignment
 ${alignment.map(a=>`### Objective ${a.index}: ${a.objective||'Untitled objective'}
Status: ${a.ready?'Complete':'Needs attention'}
Gaps: ${a.gaps.join(', ')||'None'}
Plan:
${['measure','population','sample','collection','analysis','ethics','feasibility','output','rationale'].map(k=>k+': '+(w.design[a.index-1]?.[k]||'Not recorded')).join('\n')}`).join('\n\n')||'No objectives recorded.'}

## Synthesis themes
${w.codes.map(c=>`### ${c.label}
${c.definition||'No definition recorded.'}
${[['conclusion','Interpretation'],['agreement','Agreement'],['disagreement','Disagreement / alternative explanations'],['gaps','Open questions / boundaries']].map(([key,label])=>label+': '+(c[key]||'Not recorded')).join('\n')}
Coded notes: ${w.coding.filter(x=>x.codeId===c.id).map(x=>{const n=p.evidence.find(n=>n.id===x.evidenceId);return 'E'+(p.evidence.indexOf(n)+1)+(x.note?' — '+x.note:'')}).join(', ')||'None'}`).join('\n\n')||'No themes recorded.'}

 ## Evidence comparisons
 ${w.comparisons.map(c=>{const left=p.evidence.find(n=>n.id===c.left),right=p.evidence.find(n=>n.id===c.right);return `### ${p.papers.find(s=>s.id===left?.paperId)?.title||'Evidence note'} / ${p.papers.find(s=>s.id===right?.paperId)?.title||'Evidence note'}
${c.explanation||'No explanation recorded.'}`}).join('\n\n')||'No evidence comparisons recorded.'}

## Claims and evidence
${w.claims.map((c,i)=>`### C${i+1}: ${c.text}
Status: ${c.status}
${c.links.map(l=>{const n=p.evidence.find(n=>n.id===l.evidenceId),src=p.papers.find(s=>s.id===n?.paperId);return `- ${l.relation}: ${src?.title||'Source removed'} · ${n?.locator||'location not recorded'}\n  ${n?.findings||'No finding recorded.'}`}).join('\n')||'- No evidence linked.'}`).join('\n\n')||'No claims recorded.'}

## Evidence notes
 ${p.evidence.map((n,i)=>`### E${i+1}: ${p.papers.find(s=>s.id===n.paperId)?.title||'Source removed'}
Exact passage: ${n.quote||'Not recorded'}
Finding: ${n.findings||'Not recorded'}
Method: ${n.method||'Not recorded'}
Context: ${n.context||'Not recorded'}
Limitations: ${n.limitations||'Not recorded'}
Relevance: ${n.relevance||'Not recorded'}
Location: ${n.locator||'Not recorded'}
Interpretation confidence: ${n.confidence||'Not recorded'}`).join('\n\n')||'No evidence notes recorded.'}

## Decisions and search record
${w.decisions.map(d=>'- '+d.date+' — '+d.text).join('\n')||'No decisions recorded.'}
${w.searches.map(x=>'- '+x.date+' — '+x.database+' — '+x.query+' — '+x.notes).join('\n')||'No search records recorded.'}


## Student reflection
${w.reviews.map(r=>`### ${r.prompt}
${r.answer||'No response recorded.'}`).join('\n\n')||'No rehearsal answers recorded.'}

## Bibliography
${C.bibliography(p)||'No sources recorded.'}

## Supervisor feedback prompts
- Does each claim follow from the cited evidence and its location?
- Are the population, sample, measures, collection, and analysis aligned with the question?
- What ethical or feasibility constraints should be addressed before data collection?
- Which limitations or alternative explanations could change the interpretation?

Generated locally by REI. This packet is a discussion aid; it is not an automatic scientific evaluation.
`}
 function review(){const p=get(),w=state();return heading('Be ready to explain your work.','Rehearse your reasoning, record decisions, and prepare a supervisor packet. Nothing is shared until you export and send it.')+`<div class="actions">${button('Export review package','review-export')}${button('Export supervisor packet','supervisor-export')}${button('Export readable review','review-html')}${button('Complete backup with PDFs','full-backup')}${button('Check storage','storage')}${button('Request persistent storage','persist-storage')}</div><p id="wb-storage" role="status">Browser storage is device-specific. Keep an external backup; private browsing and clearing site data can remove your work.</p>`+reviewActionQueue(p,w)+`<section class="wb-section"><h3>Defense rehearsal</h3><p>Structured prompts, grounded in your project. No AI scoring.</p>${prompts(p).map((q,i)=>`<form data-wb-form="review" class="wb-record"><input type="hidden" name="prompt" value="${esc(q)}">${area(q,'answer',w.reviews.find(r=>r.prompt===q)?.answer||'')}<button class="button secondary">Save answer ${i+1}</button></form>`).join('')}</section>`+form('decision','Add decision',area('Decision and reasoning','text','',true))+w.decisions.slice().reverse().map(d=>`<article class="wb-record"><time>${esc(new Date(d.date).toLocaleString())}</time><p>${esc(d.text)}</p>${button('Remove decision','decision-remove',d.id)}</article>`).join('')+form('search','Add search record',input('Database or website','database','',true)+input('Search query','query','',true)+area('Filters, inclusion / exclusion reasons, and results','notes'))+w.searches.map(s=>`<article class="wb-record"><h3>${esc(s.database)} · ${esc(s.query)}</h3><p>${esc(s.date)} · ${esc(s.notes)}</p>${button('Remove search record','search-remove',s.id)}</article>`).join('')+`<section class="wb-section"><h3>Project timeline</h3><p>Save a milestone before a major revision. The latest 20 snapshots retain the question and proposal text.</p>${button('Save milestone','snapshot')}${w.snapshots.map(s=>`<details class="wb-record"><summary>${esc(new Date(s.date).toLocaleString())} · ${esc(s.reason||'Milestone')}</summary><p>${esc(s.question)}</p><pre>${esc(s.proposal||'No draft text at this point.')}</pre>${button('Restore this draft','snapshot-restore',s.id)}</details>`).join('')}</section>`} function proposalTools(){return `<section class="wb-tools"><h3>Keep the evidence trail attached.</h3><p>Insert claims from the Claims view with their evidence IDs and source details. Edits to the source evidence do not silently rewrite your draft.</p><div class="actions">${button('Save draft milestone','snapshot')}${button('Export review package','review-export')}</div></section>`}
 function readingGuide(){const el=document.querySelector('#wb-reading-guide'),key=document.querySelector('[name=readingRole]')?.value,role=window.REILibraryCore?.readingRoles[key];if(el&&role)el.innerHTML=`<strong>${esc(role.look)}</strong><p>${esc(role.prompt)}</p><small>You explain the passage; REI does not infer what the paper says.</small>`;}
 function readerNotes(){readingGuide();const el=document.querySelector('#wb-reader-notes');if(!el)return;const notes=get().evidence.filter(n=>n.paperId===pdfPaper&&n.quote),roles=window.REILibraryCore?.readingRoles||{};el.innerHTML=`<div class="wb-reading-coverage"><h3>Reading trail for this source</h3><p>Build the parts that matter to your question. Counts show saved passages, not accuracy or completeness.</p><dl>${Object.entries(roles).map(([key,role])=>`<div><dt>${esc(role.label)}</dt><dd>${notes.filter(n=>n.readingRole===key).length} saved</dd></div>`).join('')}</dl></div>`+notes.map(n=>`<article class="wb-record"><span class="eyebrow">${esc(roles[n.readingRole]?.label||'Passage')} · ${esc(n.locator)}</span><blockquote>${esc(n.quote)}</blockquote><p><strong>Your interpretation:</strong> ${esc(n.findings)}</p>${button('Go to passage page','passage-page',n.page||1)}</article>`).join('');}

 async function disposePDF(doc){if(!doc)return;if(typeof doc.destroy==='function')await doc.destroy();else if(typeof doc.loadingTask?.destroy==='function')await doc.loadingTask.destroy();else if(typeof doc.cleanup==='function')await doc.cleanup()}
 async function renderPage(number){if(!pdfDoc)return;if(!Number.isFinite(number))number=1;number=Math.floor(number);const token=++readerToken;pageNumber=Math.max(1,Math.min(pdfDoc.numPages,number||1));const el=document.querySelector('#wb-pdf-status');if(!el)return;el.textContent='Rendering page…';pdfTask?.cancel();const page=await pdfDoc.getPage(pageNumber);if(token!==readerToken)return;const canvas=document.querySelector('#wb-pdf-canvas');if(!canvas)return;const viewport=page.getViewport({scale:Math.min(1.5,Math.max(280,canvas.parentElement.clientWidth)/page.getViewport({scale:1}).width)});canvas.width=viewport.width;canvas.height=viewport.height;pdfTask=page.render({canvasContext:canvas.getContext('2d'),viewport});try{await pdfTask.promise}catch(err){if(err.name==='RenderingCancelledException')return;throw err}const content=await page.getTextContent();if(token!==readerToken||!document.querySelector('#wb-pdf-text'))return;document.querySelector('#wb-pdf-text').textContent=content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('');document.querySelector('#wb-page').value=pageNumber;sessionStorage.setItem(`rei-pdf-page-${get().id}-${pdfPaper}`,String(pageNumber));el.textContent=`Page ${pageNumber} of ${pdfDoc.numPages} · ${pdfPaper?'Local PDF':''}`;selectedQuote='';readerNotes()}
 async function openPDF(){const selected=document.querySelector('#wb-reader-source')?.value;if(!selected)return;const project=get().id;const record=await docs('readonly',s=>s.get(key(project,selected)));if(!record){toast('Attach a PDF for this source first.');return}const token=++readerToken;document.querySelector('#wb-pdf-status').textContent='Opening local PDF…';pdfTask?.cancel();await disposePDF(pdfDoc);pdfDoc=null;const lib=await import('./vendor/pdfjs/pdf.min.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdfjs/pdf.worker.min.mjs',location.href).href;const task=lib.getDocument({data:new Uint8Array(await record.blob.arrayBuffer()),isEvalSupported:false,cMapUrl:new URL('./vendor/pdfjs/cmaps/',location.href).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/pdfjs/standard_fonts/',location.href).href,wasmUrl:new URL('./vendor/pdfjs/wasm/',location.href).href});const doc=await task.promise;if(token!==readerToken||get()?.id!==project||!document.querySelector('#wb-pdf-canvas')){await disposePDF(doc);return}pdfDoc=doc;pdfPaper=selected;await renderPage(Number(sessionStorage.getItem(`rei-pdf-page-${project}-${selected}`)||1))}
 function closeReader(){readerToken++;pdfTask?.cancel();disposePDF(pdfDoc).catch(()=>{});pdfDoc=null;pdfPaper='';selectedQuote=''}
 function report(){const p=get(),w=state();return `# ${p.title}\n\n## Research question\n${p.question}\n\n## Proposal\n${p.proposal}\n\n## Claims and evidence trail\n${w.claims.map((c,i)=>`### C${i+1}: ${c.text}\nStatus: ${c.status}\n${c.links.map(l=>{const n=p.evidence.find(n=>n.id===l.evidenceId);return `- ${l.relation}: E${p.evidence.indexOf(n)+1}`}).join('\n')}`).join('\n\n')}\n\n## Evidence\n${p.evidence.map((n,i)=>`### E${i+1}\nSource: ${p.papers.find(s=>s.id===n.paperId)?.title}\nLocation: ${n.locator||'Not recorded'}\nExact passage: ${n.quote||'Not recorded'}\nFinding: ${n.findings}\nMethod: ${n.method}\nContext: ${n.context}\nLimitations: ${n.limitations}\nRelevance: ${n.relevance}`).join('\n\n')}\n\n## Methods plan\n${w.design.map(d=>Object.entries(d).filter(([k])=>k!=='id').map(([k,v])=>`${k}: ${v}`).join('\n')).join('\n\n')}\n\n## Points to review\n${C.checks(p).join('\n')}\n\n## Comparisons\n${w.comparisons.map(c=>c.explanation).join('\n\n')}\n\n## Decisions\n${w.decisions.map(d=>d.date+' — '+d.text).join('\n\n')}\n\n## Search log\n${w.searches.map(s=>s.date+' — '+s.database+' — '+s.query+'\n'+s.notes).join('\n\n')}\n\n## Defense rehearsal\n${w.reviews.map(r=>r.prompt+'\n'+r.answer).join('\n\n')}\n\n## Bibliography (plain metadata; verify required citation style)\n${C.bibliography(p)}\n\nExported ${now()}. Researcher-authored records; no automated scientific validation. PDF files are not included in this review document.\n`}
 async function backup(p,includePDF=false,returnOnly=false){const copy=structuredClone(p);C.normalize(copy);if(includePDF){const records=await docs('readonly',s=>s.getAll());copy.workbench.attachments=[];for(const r of records.filter(r=>r.projectId===p.id&&p.papers.some(s=>s.id===r.paperId))){const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(r.blob)});copy.workbench.attachments.push({paperId:r.paperId,name:r.name,data})}}else delete copy.workbench.attachments;const text=JSON.stringify({version:1,project:copy},null,2);if(new Blob([text]).size>100*1024*1024)throw Error('This backup exceeds the 100 MB import limit. Reduce saved attachments before exporting.');if(returnOnly)return JSON.parse(text);download(includePDF?'rei-complete-backup.json':'rei-project.json',text,'application/json');if(includePDF){try{localStorage.setItem('rei-backup-'+p.id,JSON.stringify({updated:copy.updated,date:now()}))}catch{}dispatchEvent(new Event('rei:backup-exported'))}}
 function stageAttachments(p){const attachments=p.workbench?.attachments||[];const paperIds=new Set((p.papers||[]).map(x=>x.id));const staged=[];for(const a of attachments){if(!a||!paperIds.has(a.paperId)||typeof a.name!=='string'||!/^data:application\/pdf;base64,/.test(a.data||''))throw Error('Invalid PDF attachment.');const binary=atob(a.data.slice(a.data.indexOf(',')+1));if(!binary.startsWith('%PDF-'))throw Error('Invalid PDF attachment.');const bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));staged.push({key:key(p.id,a.paperId),projectId:p.id,paperId:a.paperId,name:a.name,blob:new Blob([bytes],{type:'application/pdf'})})}return staged}
 async function restoreAttachments(p){for(const record of stageAttachments(p))await docs('readwrite',s=>s.put(record));if(p.workbench)delete p.workbench.attachments}
