/* verify-doi.js */
(()=>{const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function verify(e){const b=e.target.closest('[data-paper-verify]');if(!b)return;const p=window.REIWorkbench.getProject()?.papers.find(x=>x.id===b.dataset.paperVerify);if(!p)return;if(!p.doi){b.textContent='No DOI recorded';return}b.disabled=true;try{const r=await fetch('https://api.crossref.org/works/'+encodeURIComponent(p.doi));if(!r.ok)throw Error();const x=(await r.json()).message||{},title=x.title?.[0]||'',authors=(x.author||[]).slice(0,3).map(a=>[a.given,a.family].filter(Boolean).join(' ')).join('; '),year=String(x.published?.['date-parts']?.[0]?.[0]||'');const diffs=[];if(title&&title.toLowerCase()!==p.title.toLowerCase())diffs.push('title differs');if(authors&&p.authors&&authors.toLowerCase()!==p.authors.toLowerCase())diffs.push('authors differ');if(year&&p.year&&year!==p.year)diffs.push('year differs');b.textContent=diffs.length?'Review differences':'Verified metadata';b.title=[title,authors,year].filter(Boolean).join(' · ')+(diffs.length?' · '+diffs.join(', '):'');b.dataset.verified='true'}catch{b.textContent='Could not verify'}finally{b.disabled=false}}document.addEventListener('click',verify)})()
