 function proposal(){return `<div class="research-section-label"><div><h2>Make your thinking coherent.</h2><p>Write your argument. Add evidence from the Evidence tab with its source attached.</p></div></div><div class="proposal-editor"><label for="project-proposal">Your working proposal</label><textarea id="project-proposal" rows="20" maxlength="200000" placeholder="Start with your research problem, then develop your question and supporting evidence…">${e(current.proposal||'')}</textarea><div class="proposal-status"><span id="proposal-count">${(current.proposal||'').trim().split(/\s+/).filter(Boolean).length} words</span><span>Saved locally as you write</span></div></div><div class="actions"><button class="button primary" data-research-export="md">Export proposal</button><button class="button secondary" data-import-learning>Review lesson drafts</button><a href="#notebook/readiness" class="text-link">Open readiness review ↗</a></div>`}
