 document.addEventListener('submit',async event=>{const form=event.target;if(!form.matches('.theme-conclusion'))return;event.preventDefault();const p=project(),code=p.workbench.codes.find(c=>c.id===form.dataset.theme),values=Object.fromEntries(keys.map(k=>[k,form.elements[k].value])),transfer=event.submitter?.name==='transfer',status=form.querySelector('.theme-save-status'),buttons=[...form.querySelectorAll('button')],disabled=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);status.textContent='Saving…';try{const added=await C.saveTheme(p,code,values,transfer,()=>window.REIWorkbench.saveProject());try{sessionStorage.removeItem(draftKey(p,code.id))}catch{}status.textContent=transfer?(added?'Conclusion saved and added to your proposal with its evidence trail.':'Conclusion saved. This exact synthesis is already in your proposal.'):'Theme conclusion saved on this device.'}catch(error){status.textContent=error.message==='Storage full'?'Could not save. Your text is still here; retry before leaving.':error.message||'Could not save. Your text is still here; retry before leaving.'}finally{buttons.forEach((b,i)=>b.disabled=disabled[i])}});
