 function analyze(raw){const csv=text(raw.csv,100001),d=dataset(csv),x=d.headers.indexOf(raw.x),y=raw.y?d.headers.indexOf(raw.y):-1,g=raw.group?d.headers.indexOf(raw.group):-1;if(x<0||raw.y&&y<0||raw.group&&g<0)throw Error('Choose columns from the current CSV.');if(y===x)throw Error('Choose a different second numeric column.');const values=[],excluded={missing:[],invalid:[]},pairs=[],groups=new Map();for(const [i,row]of d.rows.entries()){const a=number(row[x]);if(a.kind!=='number')excluded[a.kind].push(i+1);else{values.push(a.value);if(g>=0){const key=missing(row[g])?'[Missing group]':row[g].trim();if(!groups.has(key))groups.set(key,[]);groups.get(key).push(a.value);}if(y>=0){const b=number(row[y]);if(b.kind==='number')pairs.push([a.value,b.value]);}}}let r=null;if(pairs.length>=3){const a=describe(pairs.map(p=>p[0])),b=describe(pairs.map(p=>p[1]));let xx=0,yy=0,xy=0;for(const [xv,yv]of pairs){xx+=(xv-a.mean)**2;yy+=(yv-b.mean)**2;xy+=(xv-a.mean)*(yv-b.mean);}if(xx>0&&yy>0)r=Math.max(-1,Math.min(1,xy/Math.sqrt(xx)/Math.sqrt(yy)));}const frequencies=g>=0?[...d.rows.reduce((m,row)=>{const key=missing(row[g])?'[Missing group]':row[g].trim();m.set(key,(m.get(key)||0)+1);return m},new Map())].map(([label,n])=>({label,n})):[];return {rows:d.rows.length,column:d.headers[x],second:y<0?'':d.headers[y],group:g<0?'':d.headers[g],stats:describe(values),excluded,pairs,correlation:r,pairExcluded:y<0?0:d.rows.length-pairs.length,groups:[...groups].map(([label,v])=>({label,...describe(v)})),frequencies,duplicateRows:d.rows.length-new Set(d.rows.map(row=>JSON.stringify(row))).size};}
 const fmt=n=>n===null?'Not defined':Number(n.toPrecision(5)).toString();
 function analysisText(values){const a=analyze(values),s=a.stats;return '# Descriptive analysis\n\nSource: '+(text(values.source,180)||'Not recorded')+'\nColumn: '+a.column+'\nRows: '+a.rows+'; numeric observations: '+s.n+'\nMean: '+fmt(s.mean)+'; median: '+fmt(s.median)+'; sample SD: '+fmt(s.sd)+'; min: '+fmt(s.min)+'; max: '+fmt(s.max)+'\nMissing numeric rows: '+(a.excluded.missing.join(', ')||'None')+'\nInvalid numeric rows: '+(a.excluded.invalid.join(', ')||'None')+'\n'+(a.second?'Paired column: '+a.second+'; complete pairs: '+a.pairs.length+'; omitted pairs: '+a.pairExcluded+'; Pearson r: '+fmt(a.correlation)+'\n':'')+(a.group?'Group summaries:\n'+a.groups.map(g=>g.label+': n='+g.n+', mean='+fmt(g.mean)+', median='+fmt(g.median)+', sample SD='+fmt(g.sd)).join('\n')+'\n':'')+'\nResearcher notes: '+(text(values.notes,2000)||'Not recorded')+'\n\nRows are excluded only from the relevant numeric calculation; original CSV is retained. Missing markers: blank, NA, N/A, null and NaN. Sample SD uses n−1. Pearson r describes linear association; repeated observations, selection, outliers and missingness require review. No significance test, causal effect or population generalization is established.\n';}
 function methodReview(v){const issues=[];const add=(title,detail)=>issues.push({title,detail});if(v.aim==='experience'&&v.evidence!=='accounts')add('Experience needs suitable accounts','Use interviews or another justified source of accounts, or revise the aim to describe the numeric records.');if(v.aim==='relationship'&&(!text(v.second).trim()||v.evidence==='accounts'))add('Define two measurable constructs','Specify both constructs and suitable measures. Accounts alone do not estimate a numeric relationship.');if(v.aim==='effect'&&v.evidence==='accounts')add('An effect estimate needs a defined outcome measure','Accounts can illuminate experience or process; explain how the effect outcome will be measured and compared, or revise the aim.');if(v.aim==='effect'&&!['randomized','comparison'].includes(v.design))add('An effect claim needs a defensible comparison','A one-time survey or a change over time does not isolate an intervention effect. Consider a bounded descriptive or feasibility question.');if(v.analysis==='themes'&&v.evidence==='numeric')add('Themes need interpretable qualitative material','Explain the text/accounts and the interpretive process, or choose an analysis suited to the recorded numbers.');if(['correlation','summary'].includes(v.analysis)&&v.evidence==='accounts')add('The proposed numeric analysis needs defined measurements','Use an appropriate qualitative analysis, or justify how constructs will be measured numerically.');if(v.scope==='population'&&v.sampling!=='probability')add('Selection limits population estimates','Describe the sampled setting. Population estimates need a justified selection process and attention to coverage and nonresponse.');if(!text(v.measure).trim())add('Define what will be observed or measured','Name the construct and the actual indicator, instrument or interview focus. A topic label alone does not define a measure.');return issues;}
 function reviewValues(raw){const enums={aim:['experience','describe','relationship','effect'],evidence:['accounts','numeric','both'],design:['interviews','one-time','beforeafter','comparison','randomized'],analysis:['themes','summary','correlation','comparison'],sampling:['convenience','purposeful','probability'],scope:['local','population']},v={};for(const [key,choices]of Object.entries(enums)){if(!choices.includes(raw[key]))throw Error('Choose a valid '+key+'.');v[key]=raw[key];}v.measure=text(raw.measure,1000);v.second=text(raw.second,1000);return v;}
 function saveReview(p,raw,uid,date){const v=reviewValues(raw),issues=methodReview(v),key='alignment:'+JSON.stringify(v);if(p.workbench.decisions.some(d=>d.creatorKey===key))return {added:0,skipped:1};p.workbench.decisions.push({id:uid(),date,creatorKey:key,text:'Rule-based alignment review\n'+Object.entries(v).map(([key,val])=>key+': '+val).join('\n')+'\n'+(issues.map(i=>i.title+': '+i.detail).join('\n')||'No predefined mismatch detected.')+'\nThis review does not establish scientific validity. Discuss the measures, design and interpretation with a supervisor.'});return {added:1,skipped:0};}
 function claimReview(value,design='unknown'){const issues=[];if(/\b(prov(?:e|es|en)|caus(?:e|es|ed)|leads? to|results? in|improves?)\b/i.test(value)&&!['experiment','randomized'].includes(design))issues.push('Causal wording detected. Check whether the design supports attribution; an association or account alone does not.');if(/\b(all students|every student|all universities|everyone|always|never)\b/i.test(value))issues.push('Broad wording detected. Explain how the population, selection and setting support this scope.');return issues;}
 function nextStep(p){const w=p.workbench||{},room=(key)=>'#research/'+p.id+'/'+key;if(!p.question?.trim())return {label:'Shape a question you can investigate',why:'Your project does not yet have a recorded question.',href:'#create/question'};if(!p.papers.length)return {label:'Find a source for this question',why:'Start with one relevant study, then inspect its original methods and results.',href:'#create/papers'};if(!p.evidence.length)return {label:'Read one source and capture a useful passage',why:'A saved reference needs an interpretation and a source location before it can support your argument.',href:room('reader')};if(!(w.claims||[]).length)return {label:'Connect a claim to your evidence',why:'You have evidence notes. Explain one contribution and link its supporting or challenging notes.',href:room('claims')};if((w.claims||[]).some(c=>!c.links.length))return {label:'Give an unlinked claim an evidence trail',why:'At least one recorded claim has no evidence link.',href:room('claims')};if(!(w.design||[]).length)return {label:'Plan how your question can be answered',why:'Define the evidence, measure, selection and analysis you will need.',href:room('design')};const gaps=W.alignment(p).find(d=>d.gaps.length);if(gaps)return {label:'Complete the method plan for objective '+gaps.index,why:'Still missing: '+gaps.gaps.join(', ')+'.',href:room('design')};if(!p.proposal.trim())return {label:'Develop a source-linked proposal',why:'Use your recorded claims and methods to explain a bounded plan. Keep uncollected results clearly proposed.',href:room('proposal')};return {label:'Review the reasoning and prepare a handoff',why:'Recorded fields are a starting point. Review the sources, design and boundaries, then keep a portable copy.',href:room('review')};}
 function comparisons(p){return p.papers.map(s=>{const notes=p.evidence.filter(n=>n.paperId===s.id);const join=key=>[...new Set((key==='findings'?notes.filter(n=>!n.readingRole||n.readingRole==='finding'):notes).map(n=>n[key]?.trim()).filter(Boolean))].join('\n');return {source:s.title,paperId:s.id,notes:notes.length,population:join('context')||join('sample'),method:join('method'),finding:join('findings'),limitation:join('limitations'),locations:join('locator')};});}
 function normalize(raw){raw=raw&&typeof raw==='object'?raw:{};const out={version:1,papers:{},analysis:{csv:'',source:'',x:'',y:'',group:'',notes:''}};for(const key of Object.keys(out.analysis))out.analysis[key]=text(raw.analysis?.[key],key==='csv'?100000:key==='notes'?2000:180);out.analysis.run=raw.analysis?.run===true;if(out.analysis.run){try{analyze(out.analysis)}catch{out.analysis.run=false;}}for(const p of D.studies){const r=raw.papers?.[p.id];if(!r||typeof r!=='object')continue;out.papers[p.id]={choice:Number.isInteger(r.choice)&&r.choice>=0&&r.choice<4?r.choice:null,reason:text(r.reason,1500),revealed:r.revealed===true};}return out;}
 function validateProject(p){const w=p.workbench||{};if(w.analyses!==undefined){if(!Array.isArray(w.analyses)||w.analyses.length>20)throw Error('Invalid analysis records.');for(const a of w.analyses){if(a.version!==1||typeof a.id!=='string'||typeof a.date!=='string'||!a.values)throw Error('Invalid analysis record.');for(const key of ['csv','source','x','y','group','notes'])if(typeof a.values[key]!=='string')throw Error('Invalid analysis values.');analysisText(a.values);}}if(p.handoff!==undefined){const h=p.handoff;if(h.version!==1||!['originId','revisionId','createdAt','fromLabel','nextAction','baseUpdated'].every(k=>typeof h[k]==='string'&&h[k].length<=2000))throw Error('Invalid project handoff.');}return p;}
